// feature_extractor/homograph.js — the IDN homograph module's features, in the
// extension's service worker.
//
// The homograph attack is a property of the DOMAIN NAME, so the hostname is a
// legitimate input for this module (it is not a lab-, kit- or capture-specific
// artefact). The features are computed here from the page's hostname and stored
// in the tab's feature vector; the model then reads them through the
// allowlist projection like every other module.
//
// The extractor and its data are generated by homograph_module/export_js.py and
// copied in by homograph_module/sync_to_extension.sh.

import { HomographData } from '../models/homograph_data.js';
import { HomographFeatures } from '../models/homograph_features.js';

const FEATURES = HomographFeatures;

// The reference list is built once — it is 341 domains, and rebuilding it per
// navigation would be pure waste.
let REFS = null;

function refs() {
  if (!REFS) REFS = FEATURES.defaultRefs();
  return REFS;
}

// One extraction per hostname. extract() runs a Levenshtein against every
// reference domain, which is not free.
const CACHE = new Map();
const CACHE_LIMIT = 512;

/**
 * Extract the homograph features for a hostname.
 * @returns {{features: Object, target: string|null, unicodeHost: string}|null}
 */
export function homographFeatures(hostname) {
  if (!hostname) return null;
  const key = hostname.toLowerCase();
  const hit = CACHE.get(key);
  if (hit) return hit;

  let out = null;
  try {
    const r = FEATURES.extract(key, refs());
    out = { features: r.features, target: r.target || null, unicodeHost: r.unicodeHost };
  } catch (e) {
    console.warn('[Visor] homograph extraction failed', e);
  }

  if (CACHE.size >= CACHE_LIMIT) CACHE.clear();
  CACHE.set(key, out);
  return out;
}

/** The feature names, in the order the compiled model expects. */
export function homographFeatureNames() {
  return FEATURES.FEATURE_ORDER;
}
